/**
 * issue #90: Activity-side #89 suspension adapter for the stock Node-RED
 * fixed-delay `delay` node - `node.type === "delay"` with
 * `pauseType === "delay"` ONLY.
 *
 * This is the ONLY Delay-specific file in the runtime. The generic #89 ABI
 * (`suspension.js`/`activities.js`/`workflows.js`) knows nothing about
 * Delay, and `workflows.js` must never gain a `node.type === "delay"`
 * check (the issue's hard architecture constraint - see its "Rejected
 * shape" section).
 *
 * Every other stock Delay mode (rate limit, queue, timed queue, random,
 * burst, reset/flush control messages, etc.) is explicitly out of scope
 * for this PoC: `plan()` returns `undefined` for all of them, which falls
 * through to today's ordinary `node.receive()` Activity path completely
 * unchanged (see `activities.js`'s `suspensionAdapter.plan` seam).
 *
 * issue #97: `worker.js` no longer installs this adapter by default - it is
 * now opt-in (`options.durableFixedDelay` / CLI `--durable-fixed-delay`).
 * Reason (see `worker.js`'s wiring docblock for the full argument): stock
 * Delay's `reset`/`flush` control messages are handled entirely against a
 * single live node instance's process-local `idList`
 * (`89-delay.js:129-142`), but this runtime starts a BRAND NEW, separately
 * addressed Workflow Execution per source-ingress event
 * (`worker.js:createOnIngress`'s `ingress-<ts>-<rand>` Workflow ID) - an
 * ordinary message durably suspended in Workflow A and a later
 * `reset`/`flush` message reaching the SAME Delay node almost always belong
 * to a DIFFERENT Workflow Execution B, with no shared state connecting the
 * two. This file's `plan()` already refuses to suspend `reset`/`flush`
 * themselves (below), but that is not sufficient for parity: it only stops
 * a control message from becoming ANOTHER durable wait, it cannot make that
 * control message cancel/release a wait some OTHER already-in-flight
 * Workflow Execution is durably sitting on. Exact stock parity would
 * require a durable, shared, cross-Workflow "who is currently suspended at
 * this Delay node" registry - exactly the generic distributed-timer/queue
 * subsystem the issue explicitly rules out building for one stock node.
 * Callers who opt in accept this documented gap (see the runtime package
 * README's "Fixed Delay (durable, opt-in)" section); callers who do not
 * opt in get byte-identical stock `reset`/`flush` behavior, because no
 * ordinary Delay message is ever durably suspended at all.
 *
 * --- plan() ---
 * Reads the LIVE stock node's already-normalized `.timeout` (milliseconds
 * - `89-delay.js`'s constructor converts `timeoutUnits` into `this.timeout`
 * once, at node-construction time) and its `.pauseType`. Never calls the
 * stock node's own `receive()`/timer - returns a #89 timer suspension
 * immediately, with `continuation: null` (no extra plan-time state is
 * needed: `resume()` below gets the ORIGINAL `msg` back from the Workflow
 * unchanged, per `workflows.js`'s `scheduleSuspension`).
 *
 * --- resume() ---
 * Once the durable Temporal timer fires, reproduces stock Delay's
 * `pauseType === "delay"` firing semantics (`89-delay.js`: `send(msg);
 * done();`, no further completion contract for this mode) via
 * `capture.routeSend()` (#90's generic, non-Delay-specific Capture
 * helper) - so the resolved destination comes from Node-RED's own
 * `preRoute` hook, never a raw wire-graph lookup.
 */

"use strict";

function createDelaySuspensionAdapter({ capture }) {
    function plan(node, msg) {
        if (!node || node.type !== "delay" || node.pauseType !== "delay") {
            return undefined;
        }
        // issue #90 finding: stock Delay's constructor only actually
        // computes `this.timeout` via numeric multiplication for
        // minutes/hours/days/(default seconds) - for `timeoutUnits ===
        // "milliseconds"` it assigns `n.timeout` UNCHANGED
        // (`89-delay.js`'s constructor), which is a raw string whenever the
        // node's JSON config stored it as one (as Node-RED editor configs
        // commonly do). Coerce here rather than trusting the live node's
        // own type.
        const durationMs = Number(node.timeout);
        if (!Number.isFinite(durationMs) || !(durationMs > 0)) {
            return undefined;
        }
        // issue #90 PoC scope: `reset`/`flush` control messages drive the
        // stock node's buffered-list bookkeeping (`idList`/
        // `clearDelayList`/`flushDelayList`), which this PoC's one-message-
        // one-timer model does not reproduce - fall through to the
        // ordinary local path for them rather than pretending they are
        // durably supported.
        if (msg && (Object.prototype.hasOwnProperty.call(msg, "reset") || Object.prototype.hasOwnProperty.call(msg, "flush"))) {
            return undefined;
        }
        return { type: "timer", durationMs: durationMs, continuation: null };
    }

    async function resume(node, msg) {
        const routed = capture.routeSend(node, msg, () => node.send(msg));
        return { sends: routed.sends };
    }

    return { plan, resume };
}

module.exports = { createDelaySuspensionAdapter };
